/**
 * Shape of `data/registry.json`: everything the MCP server knows about the c2n components, generated by
 * `scripts/build-registry.ts` from the component manifests, the docs site content and the theme package.
 */
export interface Registry {
  schemaVersion: 1
  /** lerna.json version of the published packages. */
  c2nVersion: string
  categories: string[]
  /** Keyed by component id (the docs page id: `button`, `feather-icons`, `chatbot`). */
  components: Record<string, ComponentEntry>
  /** Tag → component id (`c2-tab` → `tabs`). Icon tags resolve through `tagPattern`. */
  tagIndex: Record<string, string>
  /** npm package → component id. */
  packageIndex: Record<string, string>
  theme: ThemeEntry
  guides: Record<GuideTopic, string>
}

export type GuideTopic = 'workflow' | 'theming' | 'variant-components' | 'frameworks'

export interface ComponentEntry {
  id: string
  package: string
  title: string
  description: string
  intro?: string
  category: string
  /** `stable` has a docs page; `undocumented` is published and built but has no page yet. */
  status: 'stable' | 'undocumented'
  docsUrl: string
  /** One entry per custom element in the package (`tabs` has `c2-tabs` and `c2-tab`). */
  elements: ElementEntry[]
  /** Icon sets: the tag pattern (`c2-feather-{name}`) and the icon names. */
  tagPattern?: string
  icons?: string[]
  composition: { internal: string[]; slotted: string[]; usedBy: string[] }
  /** `umbrella`: the `@c2n/components` entry that registers this package, when the umbrella includes it. */
  install: { npm: string; import: string; importClass: string; umbrella?: string }
  presets?: { html: string; items: Preset[] }
  examples: Example[]
  hasGallery: boolean
}

export interface ElementEntry {
  tag: string
  className: string
  /** Import specifier of the module defining the element, e.g. `@c2n/tabs/tab.js`. */
  modulePath: string
  description: string
  attributes: { name: string; type: string; default?: string; description?: string }[]
  /** Public instance properties, attribute-backed or not (`rows`, `renderCell`): what a property binding may set. */
  properties?: string[]
  slots: { name: string; description?: string }[]
  events: { name: string; type?: string; description?: string }[]
  cssParts: { name: string; description?: string }[]
  cssProperties: CssProperty[]
}

export interface CssProperty {
  name: string
  type: string
  default?: string
  /** Part segment(s) joined with `/`, `''` for the root. */
  part: string
  state?: string
  property: string
  /** `--c2-theme--*` token the base theme maps this variable to, when any. */
  token?: string
  description?: string
}

export interface Example {
  kind: 'usage' | 'gallery' | 'preview'
  label: string
  /** Gallery cards: `<section>--<label>`, unique within the component; `get_examples` also accepts it as `label`. */
  slug?: string
  section?: string
  /** What the example demonstrates: the curated description, else `summary`. */
  description?: string
  /** Gallery cards: generated from the CSS and markup (which parts, states and attributes the card changes). */
  summary?: string
  /** Gallery cards: PNG captures of the rendered card on the docs site, in the light and the dark theme. */
  screenshots?: { light: string; dark: string }
  /** Gallery cards: the docs page showing the card live. */
  galleryUrl?: string
  /** Situation in which this pattern is appropriate. */
  useWhen?: string
  /** Accessibility behavior or responsibility worth preserving. */
  accessibility?: string
  /** True only for a gallery baseline named Default with no c2n CSS-variable overrides. */
  isDefault?: boolean
  /** c2 custom-element tags present in the example markup. */
  tags?: string[]
  html: string
  /**
   * Gallery cards: colour literals equal to a theme token's value are served as `var(--c2-theme--…, literal)`, so a
   * copied card follows the application's theme and dark mode; the remaining literals are the card's own accents.
   */
  css?: string
}

export interface Preset {
  name: string
  description?: string
  css: Record<string, string>
  attributes?: Record<string, string>
}

export interface ThemeToken {
  name: string
  category: string
  light: string | null
  dark?: string
  description: string
  /** Number of component variables mapped to this token. */
  usedBy: number
}

export interface ThemeEntry {
  package: string
  install: { npm: string; imports: string[] }
  tokens: ThemeToken[]
  /** Component variable → token. */
  mapping: Record<string, string>
  darkMode: string
}
